// Windows can't replace a running executable, so no installer can update
// entire in place while it runs. For Scoop this is acute: the live
// entire.exe holds its own shim open, so scoop can't relink or uninstall it
// mid-run (install leaves the shim on the old package, and uninstall fails
// with "still running"). Windows therefore joins the paths that can't
// prompt: print the command, run nothing.
//
// Those paths all return plain skip, not skipUntilNextVersion, so the nudge
// returns every 24h until the user updates. With no prompt there is no
// choice to remember — and on Windows that is deliberate while the Scoop
// rename migration is live.
if goos == goosWindows || os.Getenv(envKillSwitch) != "" || !interactive.CanPromptInteractively() || !isTerminalOut(w) {
	printNotification(w, currentVersion, latestVersion)
	fmt.Fprintf(w, "To update, run:\n  %s\n", cmdStr)
	return autoUpdateActionSkip
}

